private.ai_budget_source_admit:
declare s private.ai_budget_operation_sources%rowtype;o private.ai_budget_operations%rowtype;
begin
 if private.ai_budget_source_ready() is not true then raise exception 'AI_SOURCE_UNAVAILABLE' using errcode='23514';end if;
 select * into s from private.ai_budget_operation_sources where operation_id=p_operation for share skip locked;
 if not found then raise exception 'AI_SOURCE_UNREGISTERED' using errcode='23514';end if;
 select * into o from private.ai_budget_operations where id=p_operation;
 if not found or private.ai_budget_source_valid(s,o) is not true then raise exception 'AI_SOURCE_BINDING' using errcode='23514';end if;
 perform private.ai_budget_source_lock(s.owner_id,s.organization_id,s.analysis_id,s.resume_version_id,s.resume_id);
end;

private.ai_budget_source_guard:
declare s private.ai_budget_operation_sources%rowtype;
begin
 if tg_table_name='ai_budget_operation_sources' then
  if tg_op<>'INSERT' then raise exception 'AI_SOURCE_IMMUTABLE' using errcode='23514';end if;
  if new.operation_id is distinct from private.ai_budget_source_operation_id(new.owner_id,new.organization_id,new.analysis_id,new.resume_version_id,new.request_nonce)
    or new.kind<>'legacy_rewrite' or not isfinite(new.registered_at) or new.registered_at>clock_timestamp()
    then raise exception 'AI_SOURCE_BINDING' using errcode='23514';end if;
  perform private.ai_budget_source_lock(new.owner_id,new.organization_id,new.analysis_id,new.resume_version_id,new.resume_id);
 elsif tg_table_name='ai_budget_operations' then
  if private.ai_budget_source_ready() is not true then raise exception 'AI_SOURCE_UNAVAILABLE' using errcode='23514';end if;
  select * into s from private.ai_budget_operation_sources where operation_id=new.id for share skip locked;
  if not found or private.ai_budget_source_valid(s,new) is not true then raise exception 'AI_SOURCE_UNREGISTERED' using errcode='23514';end if;
  perform private.ai_budget_source_lock(s.owner_id,s.organization_id,s.analysis_id,s.resume_version_id,s.resume_id);
 elsif tg_op='INSERT' then
  perform private.ai_budget_source_admit(new.operation_id);
 elsif old.state='reserved' and new.state='dispatched' then
  perform private.ai_budget_source_admit(new.operation_id);
 end if;
 return new;
end;

public.ai_budget_reserve_source_next:
declare s private.ai_budget_operation_sources%rowtype;root_id uuid;op_id uuid;old_op uuid;binding text;reply jsonb;stamp timestamptz;
begin
 if private.ifo_keys(p_source,array['schemaVersion','kind','analysisId','resumeVersionId','requestNonce']) is not true
  or p_source->>'schemaVersion' is distinct from 'ai-budget-source/1.0.0' or p_source->>'kind' is distinct from 'legacy_rewrite'
  or jsonb_typeof(p_source->'analysisId') is distinct from 'string' or p_source->>'analysisId' collate "C" !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  or jsonb_typeof(p_source->'resumeVersionId') is distinct from 'string' or p_source->>'resumeVersionId' collate "C" !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  or jsonb_typeof(p_source->'requestNonce') is distinct from 'string' or p_source->>'requestNonce' collate "C" !~ '^[ -~]{1,128}$'
  or p_request ? 'attemptOrdinal' or private.ai_budget_request_valid(p_request||'{"attemptOrdinal":1}'::jsonb,'reserve') is not true
  or p_request->>'surface' is distinct from 'rewrite' or p_user_id is null or p_organization_id is null then return private.ai_budget_denied('AI_BUDGET_INVALID');end if;
 if private.ai_budget_source_ready() is not true then return private.ai_budget_denied('AI_BUDGET_UNAVAILABLE');end if;
 op_id:=private.ai_budget_source_operation_id(p_user_id,p_organization_id,(p_source->>'analysisId')::uuid,(p_source->>'resumeVersionId')::uuid,p_source->>'requestNonce');
 if p_request->>'operationId' is distinct from op_id::text then return private.ai_budget_denied('AI_BUDGET_CONFLICT');end if;
 -- No retained OP1 state is safe to silently retry under OP2: its parent is unbound.
 old_op:=private.ai_budget_source_uuid(E'AIBUDGET-OP1\n',array[p_user_id::text,p_organization_id::text,'rewrite',p_source->>'requestNonce']);
 if exists(select 1 from private.ai_budget_operations where id=old_op) then return private.ai_budget_denied('AI_BUDGET_CONFLICT');end if;
 binding:=private.ai_budget_binding_sha256(p_user_id,p_organization_id,p_request);
 root_id:=private.ai_budget_source_lock(p_user_id,p_organization_id,(p_source->>'analysisId')::uuid,(p_source->>'resumeVersionId')::uuid,null);
 if exists(select 1 from private.ai_budget_operations where id=old_op) then return private.ai_budget_denied('AI_BUDGET_CONFLICT');end if;
 -- Denied envelopes do not abort old reserve_next. The inner subtransaction MUST.
 begin
  select * into s from private.ai_budget_operation_sources where operation_id=op_id for share skip locked;
  if found then
   if (s.owner_id,s.organization_id,s.kind,s.analysis_id,s.resume_id,s.resume_version_id,s.request_nonce,s.binding_sha256)
     is distinct from (p_user_id,p_organization_id,'legacy_rewrite'::text,(p_source->>'analysisId')::uuid,root_id,(p_source->>'resumeVersionId')::uuid,p_source->>'requestNonce',binding)
     then raise exception 'AI_SOURCE_BINDING' using errcode='23514';end if;
  else
   if exists(select 1 from private.ai_budget_operations where id=op_id) then return private.ai_budget_denied('AI_BUDGET_CONFLICT');end if;
   stamp:=clock_timestamp();
   insert into private.ai_budget_operation_sources values(op_id,p_user_id,p_organization_id,'legacy_rewrite',(p_source->>'analysisId')::uuid,root_id,(p_source->>'resumeVersionId')::uuid,p_source->>'requestNonce',binding,stamp);
  end if;
  reply:=public.ai_budget_reserve_next(p_user_id,p_organization_id,p_request);
  if reply->>'schemaVersion' is distinct from 'ai-budget/1.0.0' or reply->>'status' is distinct from 'ok'
    or reply->'receipt'->>'operationId' is distinct from op_id::text or reply->'receipt'->>'bindingSha256' is distinct from binding
    then raise exception 'AI_SOURCE_RESERVE_ROLLBACK' using errcode='P0S01';end if;
 exception when sqlstate 'P0S01' then
  if reply->>'schemaVersion'='ai-budget/1.0.0' and reply->>'status'='denied' and private.ifo_keys(reply,array['schemaVersion','status','code'])
    and reply->>'code' in ('AI_BUDGET_INVALID','AI_BUDGET_UNAVAILABLE','AI_BUDGET_DISABLED','AI_BUDGET_DENIED','AI_BUDGET_EXHAUSTED','AI_BUDGET_CONFLICT','AI_BUDGET_STATE','AI_BUDGET_BLOCKED')
    then return reply;end if;
  return private.ai_budget_denied('AI_BUDGET_UNAVAILABLE');
 end;
 return reply;
exception when others then return private.ai_budget_denied('AI_BUDGET_UNAVAILABLE');
end;

public.ai_budget_reserve_next:
declare
  organization_owner uuid;
  chosen_ordinal integer;
begin
  if p_user_id is null or p_organization_id is null or jsonb_typeof(p_request) is distinct from 'object'
    or p_request ? 'attemptOrdinal'
    or not private.ai_budget_request_valid(p_request||'{"attemptOrdinal":1}'::jsonb,'reserve') then
    return private.ai_budget_denied('AI_BUDGET_INVALID');
  end if;
  select owner_id into organization_owner from public.organizations where id=p_organization_id for update;
  if not found or organization_owner<>p_user_id then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  perform 1 from public.memberships where organization_id=p_organization_id and user_id=p_user_id
    and role in ('owner','admin','member') for update;
  if not found or not private.try_candidate_privacy_write(p_user_id) then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;

  select a.ordinal into chosen_ordinal from private.ai_budget_attempts a
    where a.id=(p_request->>'attemptId')::uuid and a.organization_id=p_organization_id;
  if not found then
    select coalesce(max(a.ordinal),0)+1 into chosen_ordinal from private.ai_budget_attempts a
      join private.ai_budget_operations o on o.id=a.operation_id
      where o.id=(p_request->>'operationId')::uuid and o.organization_id=p_organization_id and o.user_id=p_user_id;
  end if;
  if chosen_ordinal>3 then return private.ai_budget_denied('AI_BUDGET_EXHAUSTED'); end if;
  return private.ai_budget_transition(p_user_id,p_organization_id,
    p_request||jsonb_build_object('attemptOrdinal',chosen_ordinal),'reserve');
exception
  when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return private.ai_budget_denied('AI_BUDGET_INVALID');
  when others then return private.ai_budget_denied('AI_BUDGET_UNAVAILABLE');
end;

public.claim_canonical_rewrite_dispatch:
declare a public.analyses%rowtype; op private.canonical_rewrite_operations%rowtype; ctx jsonb; budget jsonb;
begin
  a:=private.canonical_rewrite_owner(p_user_id,p_analysis_id);
  select * into strict op from private.canonical_rewrite_operations where owner_id=p_user_id and analysis_id=p_analysis_id and operation_id=p_operation_id for update;
  if op.binding_sha256 is distinct from p_binding_sha256 or op.organization_id is distinct from a.organization_id then perform private.correction_fail('conflict'); end if;
  if op.state<>'reserved' then return jsonb_build_object('operation',private.canonical_rewrite_operation(op,false),'budget',null); end if;
  if private.canonical_rewrite_ready() is not true then perform private.correction_fail('unavailable'); end if;
  perform private.canonical_rewrite_consent(p_user_id,a.organization_id);
  ctx:=public.read_canonical_rewrite_context(p_user_id,p_analysis_id,jsonb_build_object('canonicalVersionId',op.request->'canonicalVersionId','requirementVersionId',op.request->'requirementVersionId'),op.policy);
  if ctx->>'bindingSha256' is distinct from op.binding_sha256
    or ctx->'relationshipContext'->'heads'->'canonicalHeadId' is distinct from op.request->'canonicalVersionId'
    or ctx->'relationshipContext'->'heads'->'requirementHeadId' is distinct from op.request->'requirementVersionId' then perform private.correction_fail('conflict'); end if;
  if p_budget is not null and p_budget<>'null'::jsonb then
    if private.evidence_keys(p_budget,array['p_user_id','p_organization_id','p_request']) is not true
      or p_budget->>'p_user_id' is distinct from p_user_id::text or p_budget->>'p_organization_id' is distinct from a.organization_id::text
      or p_budget->'p_request'->>'operationId' is distinct from p_operation_id::text
      or p_budget->'p_request'->>'surface' is distinct from 'rewrite'
      or p_budget->'p_request'->>'model' is distinct from op.policy->>'model'
      or p_budget->'p_request'->>'promptPolicyVersion' is distinct from op.policy->>'promptVersion'
      or p_budget->'p_request'->>'payloadSha256' is distinct from op.binding_sha256 then perform private.correction_fail('invalid'); end if;
    budget:=public.ai_budget_claim_dispatch(p_user_id,a.organization_id,p_budget->'p_request');
    -- A denied/replayed budget claim must roll back the operation claim as well.
    if budget->>'status' is distinct from 'ok' or budget->'receipt'->'dispatchAllowed' is distinct from 'true'::jsonb then
      return jsonb_build_object('operation',private.canonical_rewrite_operation(op,false),'budget',budget); end if;
  end if;
  update private.canonical_rewrite_operations set state='dispatched',claimed_at=clock_timestamp()
    where owner_id=p_user_id and analysis_id=p_analysis_id and operation_id=p_operation_id returning * into op;
  return jsonb_build_object('operation',private.canonical_rewrite_operation(op,true),'budget',budget);
end;

public.claim_initial_feedback_dispatch:
declare a public.analyses%rowtype;op private.initial_feedback_operations%rowtype;att private.initial_feedback_attempts%rowtype;
  original jsonb;ctx jsonb;pol jsonb;budget jsonb:=null;req jsonb;
begin
  if p_analysis_id is null or p_operation_id is null or p_attempt_id is null or p_binding_sha256 is null
    or p_binding_sha256 collate "C" !~ '^[a-f0-9]{64}$' or private.legacy_scoring_lease(p_lease) is not true then perform private.ifo_fail('invalid');end if;
  if private.initial_feedback_operation_ready() is not true then perform private.ifo_fail('unavailable');end if;
  a:=private.legacy_scoring_access(p_analysis_id,null);original:=private.ifo_original(a);
  select * into op from private.initial_feedback_operations where operation_id=p_operation_id and analysis_id=a.id
    and owner_id=a.owner_id and organization_id=a.organization_id for update;
  if not found or op.binding_sha256<>p_binding_sha256
    or op.binding is distinct from private.ifo_binding(original,op.binding->'policy') then perform private.ifo_fail('not_found');end if;
  select * into att from private.initial_feedback_attempts where attempt_id=p_attempt_id and operation_id=op.operation_id for update;
  if not found then perform private.ifo_fail('not_found');end if;
  if private.legacy_scoring_static_job(a.id,p_lease) is not true and att.claim_lease is distinct from p_lease then perform private.ifo_fail('not_found');end if;
  if op.state<>'open' or op.publication_id is not null or att.state<>'reserved' then
    return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),
      'dispatchAllowed',false,'replayed',true,'budget',null);
  end if;
  if a.status<>'qualitative_review' or not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
    then perform private.ifo_fail('stale');end if;
  pol:=private.ifo_selected_policy(a.organization_id,jsonb_build_object('version',op.policy_version,'sha256',op.policy_sha256));
  if pol is distinct from op.binding->'policy' then perform private.ifo_fail('stale');end if;
  ctx:=private.ifo_context(a,original);
  if ctx->>'generationEligibility'<>'eligible' or private.ifo_binding(ctx,pol) is distinct from op.binding then perform private.ifo_fail('stale');end if;
  -- The actual frozen source parser checks its source-domain/resource limits
  -- BEFORE any provider permission; it supplies no candidate qualification.
  perform private.ifp_document(ctx->'scoringContext'->'extraction'->>'text');
  perform 1 from public.consents where user_id=a.owner_id and purpose='qualitative_ai' and policy_version='candidate-ai-v1' for share skip locked;
  if not found then perform private.ifo_fail('not_found');end if;
  if pol->'budgetPolicyVersion'='null'::jsonb then
    if p_budget is not null and p_budget<>'null'::jsonb then perform private.ifo_fail('invalid');end if;
  else
    if private.ifo_keys(p_budget,array['p_user_id','p_organization_id','p_request']) is not true
      or p_budget->>'p_user_id' is distinct from a.owner_id::text or p_budget->>'p_organization_id' is distinct from a.organization_id::text
      then perform private.ifo_fail('invalid');end if;
    req:=p_budget->'p_request';
    if private.ai_budget_request_valid(req,'claim_dispatch') is not true or req->>'operationId' is distinct from op.operation_id::text
      or req->>'attemptId' is distinct from att.attempt_id::text or (req->>'attemptOrdinal')::numeric is distinct from att.ordinal::numeric
      or req->>'surface' is distinct from 'qualitative' or req->>'model' is distinct from pol->>'model'
      or req->>'promptPolicyVersion' is distinct from pol->>'promptVersion' or req->>'policyVersion' is distinct from pol->>'budgetPolicyVersion'
      or req->>'payloadSha256' is distinct from op.binding_sha256
      or (req->>'reservedOutputTokens')::numeric is distinct from (pol->>'maxOutputTokens')::numeric then perform private.ifo_fail('invalid');end if;
    -- Never wait for the inverse org -> membership order of generic R03 while
    -- already holding analysis/queue/source/membership locks. Reentrant after.
    perform 1 from public.organizations where id=a.organization_id for update skip locked;
    if not found then perform private.ifo_fail('stale');end if;
    perform 1 from public.memberships where organization_id=a.organization_id and user_id=a.owner_id
      and role in ('owner','admin','member') for update skip locked;
    if not found then perform private.ifo_fail('stale');end if;
    budget:=public.ai_budget_claim_dispatch(a.owner_id,a.organization_id,req);
    if budget->>'status'='denied' then
      return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),
        'dispatchAllowed',false,'replayed',false,'budget',budget);
    end if;
    -- An existing generic winner cannot be adopted as this still-reserved
    -- feedback attempt. Never mark/release that winner or dispatch a new one.
    if budget->>'status' is distinct from 'ok' or budget->'receipt'->'dispatchAllowed' is distinct from 'true'::jsonb then perform private.ifo_fail('stale');end if;
    if budget->'receipt'->>'attemptId' is distinct from att.attempt_id::text or budget->'receipt'->>'operationId' is distinct from op.operation_id::text
      or budget->'receipt'->'replayed' is distinct from 'false'::jsonb then perform private.ifo_fail('stale');end if;
  end if;
  if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
    or private.try_candidate_privacy_write(a.owner_id) is not true then perform private.ifo_fail('stale');end if;
  update private.initial_feedback_attempts set state='dispatched',claim_lease=p_lease,claimed_at=clock_timestamp(),
    budget_attempt_id=case when budget is null then null else att.attempt_id end
    where attempt_id=att.attempt_id and state='reserved' returning * into att;
  if not found then perform private.ifo_fail('stale');end if;
  return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),
    'dispatchAllowed',true,'replayed',false,'budget',budget);
end;

private.capture_owned_ai_operation_dispo:
declare registration private.ai_budget_operation_sources%rowtype;x record;source_row record;root_clock record;account_row private.owned_ai_deletion_dispositions%rowtype;
 capture_at timestamptz;cause text;cause_request uuid;cause_item uuid;root_id uuid;version_id uuid;scope text;analysis uuid;n integer:=0;expected integer;locked integer;
begin
 if private.owned_ai_disposition_ready() is not true or private.ai_budget_source_ready() is not true or p_owner is null
  or (p_request is not null)::integer+(p_item is not null)::integer<>1
  or current_setting('transaction_isolation') not in ('read committed','read uncommitted') then raise exception 'OWNED_AI_DISPOSITION_UNAVAILABLE' using errcode='23514';end if;
 -- Callers may already hold request/item/source rows. Never wait in reverse order.
 if not private.try_lock_candidate_owners(array[p_owner]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
 if p_request is not null then
  if p_resume is not null then raise exception 'OWNED_AI_DISPOSITION_SCOPE' using errcode='23514';end if;
  perform 1 from public.data_requests d join private.privacy_deletion_plans p on p.request_id=d.id
   where d.id=p_request and d.user_id=p_owner and d.kind='deletion' and d.status='processing'
     and d.lease_owner is not null and d.lease_expires_at>clock_timestamp() for update of d skip locked;
  if not found then raise exception 'OWNED_AI_DISPOSITION_AUTHORITY' using errcode='23514';end if;
  select * into account_row from private.owned_ai_deletion_dispositions where owner_id=p_owner;
  if not found then raise exception 'OWNED_AI_DISPOSITION_AUTHORITY' using errcode='23514';end if;
 else
  perform 1 from private.retention_items t join public.resumes r on r.id=t.resume_id and r.owner_id=t.owner_id
   where t.id=p_item and t.owner_id=p_owner and t.resume_id=p_resume and t.status='queued'
    and r.status in ('active','deleted') for update of t skip locked;
  if not found then raise exception 'OWNED_AI_DISPOSITION_AUTHORITY' using errcode='23514';end if;
  select count(*) into expected from public.resume_versions where resume_id=p_resume and owner_id=p_owner;
  select count(*) into locked from (select v.id from public.resumes r join public.resume_versions v on v.resume_id=r.id
   where r.id=p_resume and r.owner_id=p_owner and v.owner_id=p_owner for share of r,v skip locked) q;
  if expected=0 or locked<>expected then raise exception 'OWNED_AI_DISPOSITION_BUSY' using errcode='55P03';end if;
 end if;
 -- All states, including reserved/unpublished, before any candidate parent deletion.
 for x in
  select 'a12'::text kind,o.owner_id,o.organization_id,o.operation_id,o.analysis_id,null::uuid resume_id,o.source_id source_id
   from private.canonical_rewrite_operations o where o.owner_id=p_owner and (p_resume is null or exists(
    select 1 from public.resume_versions v where v.id=o.source_id and v.resume_id=p_resume and v.owner_id=p_owner and v.organization_id=o.organization_id))
  union all
  select 'a13',o.owner_id,o.organization_id,o.operation_id,o.analysis_id,o.resume_id,o.resume_version_id
   from private.initial_feedback_operations o where o.owner_id=p_owner and (p_resume is null or o.resume_id=p_resume)
  order by analysis_id,kind,operation_id loop
  n:=n+1;if n>4096 then raise exception 'OWNED_AI_DISPOSITION_LIMIT' using errcode='23514';end if;
  root_id:=x.resume_id;version_id:=x.source_id;scope:='resume_root';
  select v.resume_id into root_id from public.resume_versions v where v.id=version_id and v.owner_id=p_owner and v.organization_id=x.organization_id;
  if not found then
   if exists(select 1 from public.resume_versions where id=version_id) then raise exception 'OWNED_AI_DISPOSITION_SCOPE' using errcode='23514';end if;
   root_id:=x.resume_id;
  end if;
  if root_id is not null then
   perform 1 from public.resumes r join public.resume_versions v on v.resume_id=r.id
    where r.id=root_id and r.owner_id=p_owner and v.id=version_id and v.owner_id=p_owner and v.organization_id=x.organization_id
    for share of r,v skip locked;
   if not found and exists(select 1 from public.resume_versions where id=version_id) then raise exception 'OWNED_AI_DISPOSITION_BUSY' using errcode='55P03';end if;
  end if;
  select t.id,t.created_at into root_clock from private.retention_items t where t.owner_id=p_owner and t.resume_id=root_id order by t.created_at,t.id limit 1;
  if p_request is not null then
   capture_at:=account_row.prepared_at;cause:='account_preparation';cause_request:=account_row.first_request_id;cause_item:=null;
   if root_clock.id is not null and root_clock.created_at<capture_at then capture_at:=root_clock.created_at;cause:='resume_retirement';cause_request:=null;cause_item:=root_clock.id;end if;
  else
   if root_clock.id is null then raise exception 'OWNED_AI_DISPOSITION_AUTHORITY' using errcode='23514';end if;
   capture_at:=root_clock.created_at;cause:='resume_retirement';cause_request:=null;cause_item:=root_clock.id;
  end if;
  if root_id is null or (not exists(select 1 from public.resume_versions where id=version_id and owner_id=p_owner and resume_id=root_id)
      and root_clock.id is null) then
   scope:='historical_unresolved';capture_at:=null;cause:=null;cause_request:=null;cause_item:=null;
  end if;
  if x.kind='a12' then
   perform 1 from private.canonical_rewrite_operations o where (o.owner_id,o.analysis_id,o.operation_id)=(p_owner,x.analysis_id,x.operation_id) for update skip locked;
  else
   perform 1 from private.initial_feedback_operations o where o.operation_id=x.operation_id and o.owner_id=p_owner for update skip locked;
  end if;
  if not found then raise exception 'OWNED_AI_DISPOSITION_BUSY' using errcode='55P03';end if;
  perform private.capture_owned_ai_disposition_row(x.kind,p_owner,x.organization_id,x.operation_id,x.analysis_id,root_id,version_id,scope,cause,cause_request,cause_item,capture_at);
 end loop;
 -- Account deletion owns every R03 operation across organizations, regardless of flags.
 -- Root retirement may select ONLY the exact producer relations below.
 for x in select o.* from private.ai_budget_operations o where o.user_id=p_owner and (p_resume is null or exists(select 1 from private.ai_budget_operation_sources s where s.operation_id=o.id and s.owner_id=p_owner and s.resume_id=p_resume) or exists(
   select 1 from private.canonical_rewrite_operations c join public.resume_versions v on v.id=c.source_id
    where c.owner_id=p_owner and c.organization_id=o.organization_id and c.operation_id=o.id and v.owner_id=p_owner and v.organization_id=o.organization_id
      and v.resume_id=p_resume and o.surface='rewrite' and o.payload_sha256=c.binding_sha256
      and o.model=c.policy->>'model' and o.prompt_policy_version=c.policy->>'promptVersion'
   union all
   select 1 from private.initial_feedback_operations f join private.initial_feedback_attempts a on a.operation_id=f.operation_id
    join private.ai_budget_attempts b on b.operation_id=o.id and b.id=coalesce(a.budget_attempt_id,a.attempt_id) and private.owned_ai_feedback_budget_link(o,f,a,b)
    where f.owner_id=p_owner and f.organization_id=o.organization_id and f.resume_id=p_resume and f.operation_id=o.id
      and o.surface='qualitative' and o.payload_sha256=f.binding_sha256 and o.model=f.binding->'policy'->>'model'
      and o.prompt_policy_version=f.binding->'policy'->>'promptVersion' and o.policy_version=f.binding->'policy'->>'budgetPolicyVersion'
   union all
   select 1 from public.analyses a join public.resume_versions v on v.id=a.resume_version_id
    where a.id=o.id and a.owner_id=p_owner and a.organization_id=o.organization_id and v.owner_id=p_owner and v.organization_id=o.organization_id
      and v.resume_id=p_resume and o.surface='qualitative')) order by o.id loop
  n:=n+1;if n>4096 then raise exception 'OWNED_AI_DISPOSITION_LIMIT' using errcode='23514';end if;
  -- Registered OP2 source wins before legacy/account-only inference, in ALL states.
  if exists(select 1 from private.ai_budget_operation_sources where operation_id=x.id) then
   select * into registration from private.ai_budget_operation_sources where operation_id=x.id for share skip locked;
   if not found then raise exception 'OWNED_AI_DISPOSITION_BUSY' using errcode='55P03';end if;
   if private.ai_budget_source_valid(registration,x) is not true or registration.owner_id<>p_owner
     or (p_resume is not null and registration.resume_id<>p_resume) then raise exception 'OWNED_AI_DISPOSITION_SCOPE' using errcode='23514';end if;
   analysis:=registration.analysis_id;root_id:=registration.resume_id;version_id:=registration.resume_version_id;scope:='resume_root';
   select * into source_row from private.owned_ai_operation_dispositions d where d.kind='r03' and d.owner_id=p_owner and d.operation_id=x.id for share skip locked;
   if found then
    if (source_row.organization_id,source_row.analysis_id,source_row.resume_id,source_row.resume_version_id)
      is distinct from (registration.organization_id,analysis,root_id,version_id) then raise exception 'OWNED_AI_DISPOSITION_SCOPE' using errcode='23514';end if;
    capture_at:=source_row.prepared_at;cause:=source_row.first_cause;cause_request:=source_row.deletion_request_id;cause_item:=source_row.retention_item_id;scope:=source_row.source_scope;
   else
    if exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='r03' and d.owner_id=p_owner and d.operation_id=x.id)
      then raise exception 'OWNED_AI_DISPOSITION_BUSY' using errcode='55P03';end if;
    perform 1 from public.resumes r join public.resume_versions v on v.resume_id=r.id
      where (r.id,r.owner_id,r.organization_id,v.id,v.owner_id,v.organization_id)=(root_id,p_owner,x.organization_id,version_id,p_owner,x.organization_id) for share of r,v skip locked;
    if not found then
     scope:='historical_unresolved';capture_at:=null;cause:=null;cause_request:=null;cause_item:=null;
    else
     select t.id,t.created_at into root_clock from private.retention_items t where t.owner_id=p_owner and t.resume_id=root_id order by t.created_at,t.id limit 1;
     if p_request is not null then
      capture_at:=account_row.prepared_at;cause:='account_preparation';cause_request:=account_row.first_request_id;cause_item:=null;
      if root_clock.id is not null and root_clock.created_at<capture_at then capture_at:=root_clock.created_at;cause:='resume_retirement';cause_request:=null;cause_item:=root_clock.id;end if;
      if root_clock.id is null and exists(select 1 from public.resumes where id=root_id and status='deleted') then
       scope:='historical_unresolved';capture_at:=null;cause:=null;cause_request:=null;cause_item:=null;
      end if;
     else
      capture_at:=root_clock.created_at;cause:='resume_retirement';cause_request:=null;cause_item:=root_clock.id;
     end if;
    end if;
   end if;
   perform 1 from private.ai_budget_operations o where o.id=x.id and o.user_id=p_owner for update skip locked;
   if not found then raise exception 'OWNED_AI_DISPOSITION_BUSY' using errcode='55P03';end if;
   perform private.capture_owned_ai_disposition_row('r03',p_owner,x.organization_id,x.id,analysis,root_id,version_id,scope,cause,cause_request,cause_item,capture_at);
   continue;
  end if;
  if p_resume is null then
   -- Account capture cannot restart an already proved root-retirement deadline.
   -- Match the REAL producer binding before using any typed clock or selector.
   select d.* into source_row from private.owned_ai_operation_dispositions d
    where d.owner_id=p_owner and d.organization_id=x.organization_id and d.operation_id=x.id and (
     (d.kind='a12' and x.surface='rewrite' and exists(select 1 from private.canonical_rewrite_operations c
       where (c.owner_id,c.analysis_id,c.operation_id)=(p_owner,d.analysis_id,x.id) and c.binding_sha256=x.payload_sha256
        and c.policy->>'model'=x.model and c.policy->>'promptVersion'=x.prompt_policy_version))
     or (d.kind='a13' and x.surface='qualitative' and exists(select 1 from private.initial_feedback_operations f
       join private.initial_feedback_attempts a on a.operation_id=f.operation_id join private.ai_budget_attempts z on z.operation_id=x.id and z.id=coalesce(a.budget_attempt_id,a.attempt_id) and private.owned_ai_feedback_budget_link(x,f,a,z)
       where f.operation_id=x.id and f.owner_id=p_owner and f.binding_sha256=x.payload_sha256 and z.operation_id=x.id)))
    order by d.prepared_at nulls first,d.kind,d.analysis_id limit 1;
   if found then
    analysis:=source_row.analysis_id;root_id:=source_row.resume_id;version_id:=source_row.resume_version_id;
    scope:=source_row.source_scope;capture_at:=source_row.prepared_at;cause:=source_row.first_cause;
    cause_request:=source_row.deletion_request_id;cause_item:=source_row.retention_item_id;
   else
    select a.id analysis_id,v.resume_id,v.id resume_version_id into source_row from public.analyses a join public.resume_versions v on v.id=a.resume_version_id
     where a.id=x.id and a.owner_id=p_owner and a.organization_id=x.organization_id and v.owner_id=p_owner and v.organization_id=x.organization_id and x.surface='qualitative';
    if found then
     analysis:=source_row.analysis_id;root_id:=source_row.resume_id;version_id:=source_row.resume_version_id;scope:='resume_root';
     select t.id,t.created_at into root_clock from private.retention_items t where t.owner_id=p_owner and t.resume_id=root_id order by t.created_at,t.id limit 1;
     capture_at:=account_row.prepared_at;cause:='account_preparation';cause_request:=account_row.first_request_id;cause_item:=null;
     if root_clock.id is not null and root_clock.created_at<capture_at then capture_at:=root_clock.created_at;cause:='resume_retirement';cause_request:=null;cause_item:=root_clock.id;end if;
    elsif x.surface='build' then
     -- Standalone Build has no resume root to infer. Its first account cause is exact.
     analysis:=null;root_id:=null;version_id:=null;scope:='account_only';capture_at:=account_row.prepared_at;
     cause:='account_preparation';cause_request:=account_row.first_request_id;cause_item:=null;
    else
     -- Unbound historical qualitative/rewrite identity supplies no first source clock.
     analysis:=null;root_id:=null;version_id:=null;scope:='historical_unresolved';capture_at:=null;cause:=null;cause_request:=null;cause_item:=null;
    end if;
   end if;
  else
   -- Exact previously captured typed selector, or legacy qualitative analysis identity.
   select d.analysis_id,d.resume_id,d.resume_version_id into source_row from private.owned_ai_operation_dispositions d
    where d.owner_id=p_owner and d.organization_id=x.organization_id and d.operation_id=x.id and d.kind in ('a12','a13')
     and d.resume_id=p_resume and d.phase='prepared' and (
      (d.kind='a12' and x.surface='rewrite' and exists(select 1 from private.canonical_rewrite_operations c
        where (c.owner_id,c.analysis_id,c.operation_id)=(p_owner,d.analysis_id,x.id) and c.binding_sha256=x.payload_sha256
          and c.policy->>'model'=x.model and c.policy->>'promptVersion'=x.prompt_policy_version))
      or (d.kind='a13' and x.surface='qualitative' and exists(select 1 from private.initial_feedback_operations f
        join private.initial_feedback_attempts a on a.operation_id=f.operation_id join private.ai_budget_attempts z on z.operation_id=x.id and z.id=coalesce(a.budget_attempt_id,a.attempt_id) and private.owned_ai_feedback_budget_link(x,f,a,z)
        where f.operation_id=x.id and f.owner_id=p_owner and f.binding_sha256=x.payload_sha256 and z.operation_id=x.id)))
    order by d.kind,d.analysis_id limit 1;
   if not found then
    select a.id analysis_id,v.resume_id,v.id resume_version_id into source_row from public.analyses a join public.resume_versions v on v.id=a.resume_version_id
     where a.id=x.id and a.owner_id=p_owner and a.organization_id=x.organization_id and v.owner_id=p_owner and v.organization_id=x.organization_id and v.resume_id=p_resume;
   end if;
   if not found then raise exception 'OWNED_AI_DISPOSITION_UNAVAILABLE' using errcode='23514';end if;
   analysis:=source_row.analysis_id;root_id:=source_row.resume_id;version_id:=source_row.resume_version_id;scope:='resume_root';
   select t.id,t.created_at into root_clock from private.retention_items t where t.owner_id=p_owner and t.resume_id=p_resume order by t.created_at,t.id limit 1;
   capture_at:=root_clock.created_at;cause:='resume_retirement';cause_request:=null;cause_item:=root_clock.id;
  end if;
  perform 1 from private.ai_budget_operations o where o.id=x.id and o.user_id=p_owner for update skip locked;
  if not found then raise exception 'OWNED_AI_DISPOSITION_BUSY' using errcode='55P03';end if;
  perform private.capture_owned_ai_disposition_row('r03',p_owner,x.organization_id,x.id,analysis,root_id,version_id,scope,cause,cause_request,cause_item,capture_at);
 end loop;
end;

public.export_owned_ai_budget_sources:
declare s private.ai_budget_operation_sources%rowtype;o private.ai_budget_operations%rowtype;item jsonb;answer jsonb;rows jsonb:='[]'::jsonb;n integer:=0;bytes bigint:=1024;
begin
 if p_user_id is null then raise exception 'AI_SOURCE_EXPORT_INVALID' using errcode='22023';end if;
 if private.ai_budget_source_ready() is not true then raise exception 'AI_SOURCE_EXPORT_UNAVAILABLE' using errcode='23514';end if;
 perform 1 from auth.users where id=p_user_id;if not found then raise exception 'AI_SOURCE_EXPORT_UNAVAILABLE' using errcode='23514';end if;
 -- Entire owner set, across organizations and flags; no current source/membership filter.
 for s in select * from private.ai_budget_operation_sources where owner_id=p_user_id order by operation_id limit 4097 loop
  n:=n+1;if n>4096 then raise exception 'AI_SOURCE_EXPORT_UNAVAILABLE' using errcode='23514';end if;
  select * into o from private.ai_budget_operations where id=s.operation_id;
  if not found or private.ai_budget_source_valid(s,o) is not true then raise exception 'AI_SOURCE_EXPORT_UNAVAILABLE' using errcode='23514';end if;
  if not exists(select 1 from public.resumes r join public.resume_versions v on v.resume_id=r.id
    where (r.id,r.owner_id,r.organization_id,v.id,v.owner_id,v.organization_id)=(s.resume_id,s.owner_id,s.organization_id,s.resume_version_id,s.owner_id,s.organization_id))
   and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='r03' and d.operation_id=s.operation_id
    and (d.owner_id,d.organization_id,d.analysis_id,d.resume_id,d.resume_version_id)=(s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id)
    and d.phase='prepared' and d.source_scope='resume_root') then raise exception 'AI_SOURCE_EXPORT_UNAVAILABLE' using errcode='23514';end if;
  item:=jsonb_build_object('operationId',s.operation_id,'ownerId',s.owner_id,'organizationId',s.organization_id,'kind',s.kind,'analysisId',s.analysis_id,
   'resumeId',s.resume_id,'resumeVersionId',s.resume_version_id,'requestNonce',s.request_nonce,'bindingSha256',s.binding_sha256,'registeredAt',private.ifo_stamp(s.registered_at));
  bytes:=bytes+octet_length(convert_to(item::text,'UTF8'))+1;if bytes>33554432 then raise exception 'AI_SOURCE_EXPORT_UNAVAILABLE' using errcode='23514';end if;
  rows:=rows||jsonb_build_array(item);
 end loop;
 answer:=jsonb_build_object('schemaVersion','owned-ai-budget-sources/1.0.0','ownerId',p_user_id,'sources',rows);
 if octet_length(convert_to(answer::text,'UTF8'))>33554432 then raise exception 'AI_SOURCE_EXPORT_UNAVAILABLE' using errcode='23514';end if;
 return answer;
end;

public.export_owned_ai_disposition_recor:
declare accounts jsonb[]:=array[]::jsonb[];operations jsonb[]:=array[]::jsonb[];row_value jsonb;answer jsonb;n integer:=0;bytes bigint:=1024;
begin
 if p_user_id is null or private.owned_ai_disposition_ready() is not true then raise exception 'OWNED_AI_DISPOSITION_UNAVAILABLE' using errcode='23514';end if;
 if not private.try_lock_candidate_owners(array[p_user_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
 perform 1 from auth.users where id=p_user_id for key share skip locked;if not found then raise exception 'OWNED_AI_DISPOSITION_UNAVAILABLE' using errcode='23514';end if;
 -- Registered-source completeness is independent of current membership/flags.
 if private.ai_budget_source_ready() is not true or exists(
  select 1 from private.ai_budget_operation_sources s where s.owner_id=p_user_id
   and (exists(select 1 from private.retention_items t where t.owner_id=p_user_id and t.resume_id=s.resume_id)
    or exists(select 1 from private.owned_ai_deletion_dispositions a where a.owner_id=p_user_id)
    or not exists(select 1 from public.resumes r join public.resume_versions v on v.resume_id=r.id
      where (r.id,r.owner_id,r.organization_id,v.id,v.owner_id,v.organization_id)=(s.resume_id,s.owner_id,s.organization_id,s.resume_version_id,s.owner_id,s.organization_id)))
   and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='r03' and d.operation_id=s.operation_id
    and (d.owner_id,d.organization_id,d.analysis_id,d.resume_id,d.resume_version_id)=(s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id)))
  then raise exception 'OWNED_AI_DISPOSITION_INCOMPLETE' using errcode='23514';end if;
 -- Missing historical clocks are not an empty complete export. Only PROVED
 -- retired source relationships qualify; standalone Build is never guessed.
 if exists(select 1 from private.initial_feedback_operations o where o.owner_id=p_user_id
   and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='a13' and d.owner_id=p_user_id and d.operation_id=o.operation_id)
   and (exists(select 1 from private.initial_feedback_content_retirements r where r.operation_id=o.operation_id and r.owner_id=p_user_id)
    or exists(select 1 from private.retention_items t where t.resume_id=o.resume_id and t.owner_id=p_user_id)
    or not exists(select 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
      join public.analyses a on a.resume_version_id=v.id where v.id=o.resume_version_id and r.id=o.resume_id and a.id=o.analysis_id
       and v.owner_id=p_user_id and r.owner_id=p_user_id and a.owner_id=p_user_id)))
  or exists(select 1 from private.canonical_rewrite_operations o where o.owner_id=p_user_id
   and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='a12' and (d.owner_id,d.analysis_id,d.operation_id)=(p_user_id,o.analysis_id,o.operation_id))
   and (not exists(select 1 from public.resume_versions v join public.analyses a on a.resume_version_id=v.id
     where v.id=o.source_id and a.id=o.analysis_id and v.owner_id=p_user_id and a.owner_id=p_user_id)
    or exists(select 1 from public.resume_versions v join private.retention_items t on t.resume_id=v.resume_id and t.owner_id=v.owner_id
      where v.id=o.source_id and v.owner_id=p_user_id)))
  or exists(select 1 from private.ai_budget_operations o where o.user_id=p_user_id
   and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='r03' and d.owner_id=p_user_id and d.operation_id=o.id)
   and exists(select 1 from private.owned_ai_operation_dispositions d where d.owner_id=p_user_id and d.organization_id=o.organization_id
     and d.operation_id=o.id and d.first_cause='resume_retirement' and (
      (d.kind='a12' and o.surface='rewrite' and exists(select 1 from private.canonical_rewrite_operations c
        where (c.owner_id,c.analysis_id,c.operation_id)=(p_user_id,d.analysis_id,o.id) and c.binding_sha256=o.payload_sha256))
      or (d.kind='a13' and o.surface='qualitative' and exists(select 1 from private.initial_feedback_operations f
        join private.initial_feedback_attempts a on a.operation_id=f.operation_id join private.ai_budget_attempts z on z.operation_id=o.id and z.id=coalesce(a.budget_attempt_id,a.attempt_id) and private.owned_ai_feedback_budget_link(o,f,a,z)
         where f.operation_id=o.id and f.owner_id=p_user_id and f.binding_sha256=o.payload_sha256 and z.operation_id=o.id)))))
   then raise exception 'OWNED_AI_DISPOSITION_HISTORICAL_REPAIR' using errcode='23514';end if;
 -- Prepared account closure cannot silently omit a retained operation.
 if exists(select 1 from private.owned_ai_deletion_dispositions where owner_id=p_user_id) and (
   exists(select 1 from private.ai_budget_operations o where o.user_id=p_user_id and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='r03' and d.owner_id=p_user_id and d.operation_id=o.id))
   or exists(select 1 from private.canonical_rewrite_operations o where o.owner_id=p_user_id and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='a12' and (d.owner_id,d.analysis_id,d.operation_id)=(p_user_id,o.analysis_id,o.operation_id)))
   or exists(select 1 from private.initial_feedback_operations o where o.owner_id=p_user_id and not exists(select 1 from private.owned_ai_operation_dispositions d where d.kind='a13' and d.owner_id=p_user_id and d.operation_id=o.operation_id)))
   then raise exception 'OWNED_AI_DISPOSITION_INCOMPLETE' using errcode='23514';end if;
 for row_value in select to_jsonb(d)||jsonb_build_object('prepared_at',private.ifo_stamp(d.prepared_at),'expires_at',private.ifo_stamp(d.expires_at))
  from private.owned_ai_deletion_dispositions d where d.owner_id=p_user_id loop
  n:=n+1;bytes:=bytes+octet_length(convert_to(row_value::text,'UTF8'))+1;if n>4096 or bytes>33554432 then raise exception 'OWNED_AI_DISPOSITION_LIMIT' using errcode='23514';end if;
  accounts:=array_append(accounts,row_value);
 end loop;
 for row_value in select to_jsonb(d)||jsonb_build_object('prepared_at',private.ifo_stamp(d.prepared_at),'expires_at',private.ifo_stamp(d.expires_at),
   'effective_expires_at',case when d.expires_at is null then null else private.ifo_stamp(least(d.expires_at,a.expires_at)) end)
  from private.owned_ai_operation_dispositions d left join private.owned_ai_deletion_dispositions a on a.owner_id=d.owner_id
  where d.owner_id=p_user_id order by d.kind,d.analysis_id nulls first,d.operation_id limit 4097 loop
  n:=n+1;bytes:=bytes+octet_length(convert_to(row_value::text,'UTF8'))+1;if n>4096 or bytes>33554432 then raise exception 'OWNED_AI_DISPOSITION_LIMIT' using errcode='23514';end if;
  operations:=array_append(operations,row_value);
 end loop;
 answer:=jsonb_build_object('schemaVersion','owned-ai-disposition-export/1.0.0','ownerId',p_user_id,'accounts',to_jsonb(accounts),'operations',to_jsonb(operations));
 if octet_length(convert_to(answer::text,'UTF8'))>33554432 then raise exception 'OWNED_AI_DISPOSITION_LIMIT' using errcode='23514';end if;
 return answer;
end;

public.read_ai_budget_source_readiness:
declare ready boolean:=private.ai_budget_source_ready();
begin
 return jsonb_build_object('schemaVersion','ai-budget-source-readiness/1.0.0','profileVersion','ai-budget-source-profile/1.0.0',
  'checkerSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('private.ai_budget_source_ready()')),
  'reserveSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.ai_budget_reserve_source_next(uuid,uuid,jsonb,jsonb)')),
  'exportSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.export_owned_ai_budget_sources(uuid)')),
  'metadataSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.read_ai_budget_source_readiness()')),
  'schemaReady',ready,'reserveExecutable',ready and has_function_privilege('service_role','public.ai_budget_reserve_source_next(uuid,uuid,jsonb,jsonb)','EXECUTE'),
  'exportExecutable',ready and has_function_privilege('service_role','public.export_owned_ai_budget_sources(uuid)','EXECUTE'));
end;

private.canonical_rewrite_ready:
declare routine pg_catalog.pg_proc%rowtype; predecessor pg_catalog.pg_proc%rowtype; rel pg_catalog.pg_class%rowtype;
  target jsonb; role_name text; name text; service_oid oid:=(select oid from pg_catalog.pg_roles where rolname='service_role');
  manifest jsonb:=$cr_catalog$[
  {
    "signature": "private.canonical_rewrite_immutable()",
    "sha256": "c9112879a49deae16f5714cd898b7ab7a960e532a126f0227d443f4fecebfb1d",
    "definer": false,
    "volatility": "v",
    "resultType": "trigger",
    "language": "plpgsql",
    "acl": "owner_only"
  },
  {
    "signature": "private.canonical_rewrite_policy(jsonb)",
    "sha256": "0794d56ad1efb60d9ed5d3466f84c158abc3875a9b717955c28642158e493580",
    "definer": false,
    "volatility": "i",
    "resultType": "void",
    "language": "plpgsql",
    "acl": "owner_only"
  },
  {
    "signature": "private.canonical_rewrite_request(jsonb)",
